// =====================================================================
// news.ts — the city news feed: citywide and per-borough.
//
// Two kinds of stories:
//   • DAILY headlines, picked from the date with a seeded random number
//     so every player sees the same stories that day (no server needed).
//   • PERSONAL stories, created by what the player does (a lottery win,
//     a promotion, getting scammed). In multiplayer these become stories
//     about other players, generated by the server from game events only —
//     never typed in by players, so the feed can't be used to harass anyone.
// =====================================================================

import { bus } from '../core/bus.ts';
import { nowMs } from '../core/clock.ts';
import { Rng } from '../core/rng.ts';
import type { AreaId, GameState, NewsItem } from './types.ts';
import { WEATHER_INFO, weatherFor } from './weather.ts';

const KEEP = 40;

const CITY_POOL: [string, string][] = [
  ['🚇', 'Subway sets record: three trains arrive on time in a row'],
  ['🌭', 'Hot dog prices up 25 cents; New Yorkers threaten to riot, then pay'],
  ['🐀', 'Pizza Rat spotted again, now dragging a full calzone'],
  ['🏛️', 'Mayor promises fewer potholes; pothole on City Hall’s street disagrees'],
  ['🎭', 'Broadway revival sells out in eleven minutes'],
  ['🏀', 'Knicks fans “cautiously optimistic” for the 47th straight season'],
  ['🚕', 'Taxi drivers and rideshare drivers agree on one thing: the BQE'],
  ['🛴', 'City debates scooter rules after delivery bike breaks sound barrier'],
  ['🗽', 'Lady Liberty’s torch gets a fresh polish; tourists approve'],
  ['🌉', 'Bridge joggers vs. bridge cyclists: a truce is declared, for now'],
  ['🍕', 'Slice prices hold steady as cheese futures stabilise'],
  ['📈', 'Rents rise again. Experts: “Have you considered roommates?”'],
  ['🎆', 'Rooftop party season in full swing, landlords nervous'],
  ['🧹', 'Sanitation crews win “Best Department” in an online poll'],
];

const AREA_POOL: Record<AreaId, [string, string][]> = {
  manhattan: [
    ['🌆', 'Times Square screens go dark for 90 seconds; tourists stare at the sky'],
    ['🥯', 'Hell’s Kitchen bagel shop opens; line already around the block'],
    ['🏢', 'Midtown office tower converts three floors into apartments'],
    ['🌳', 'Bryant Park adds more chess tables after a weekend of record crowds'],
    ['🎤', 'Ninth Ave karaoke bar crowns a new Thursday-night champion'],
    ['🏙️', 'Empire State Building lights up in surprise colours tonight'],
  ],
  brooklyn: [
    ['🌉', 'Brooklyn Bridge walkway packed at sunset; photographers jostle for space'],
    ['🎧', 'Warehouse party runs until 9 AM; neighbours “mostly fine with it”'],
    ['🥖', 'Fort Greene farmers market sells out of sourdough by 10 AM'],
    ['🏀', 'Atlantic Arena crowd goes wild in overtime thriller'],
    ['☕', 'Another DUMBO café opens; local count now exceeds residents'],
    ['🎨', 'Mural festival repaints a full block of Fulton Street'],
  ],
};

/** Add a story to the feed (newest first). */
export function postNews(s: GameState, item: Omit<NewsItem, 'id' | 'at'> & { id?: string; at?: number }): void {
  const full: NewsItem = { id: item.id ?? `n-${nowMs()}-${Math.floor(Math.random() * 1e6)}`, at: item.at ?? nowMs(), ...item };
  if (s.news.some((n) => n.id === full.id)) return;
  s.news.unshift(full);
  if (s.news.length > KEEP) s.news.length = KEEP;
  bus.emit('news:posted', { id: full.id });
}

/** Post today's shared headlines (called once per New York day). */
export function postDailyNews(s: GameState, dateKey: string): void {
  const rng = new Rng(`news-${dateKey}`);
  const w = weatherFor(dateKey, 9);
  const wi = WEATHER_INFO[w];
  postNews(s, { id: `w-${dateKey}`, scope: 'city', emoji: wi.emoji, headline: `Today in NYC: ${wi.label}${w === 'rain' || w === 'storm' ? ' — bring an umbrella, expect train delays' : ''}` });
  const [ce, ch] = rng.pick(CITY_POOL);
  postNews(s, { id: `c-${dateKey}`, scope: 'city', emoji: ce, headline: ch });
  for (const area of ['manhattan', 'brooklyn'] as AreaId[]) {
    const [e, h] = rng.pick(AREA_POOL[area]);
    postNews(s, { id: `${area}-${dateKey}`, scope: area, emoji: e, headline: h });
  }
}
